var path = require('path');
var { glob } = require('glob');

module.exports = applyExtraOptions;

// Browserify's bundle() waits on `_ready` while `_pending` async work finishes.
// Honor that handshake for ignore/exclude/external globs so multi-bundle and
// extract-style pipelines do not race past unfinished path resolution.
function applyExtraOptions(b, options) {
    []
        .concat(options.ignore)
        .filter(Boolean)
        .forEach(function (i) {
            b._pending++;
            glob(i)
                .then(function (files) {
                    if (files.length === 0) {
                        b.ignore(i);
                    } else {
                        files.forEach(function (file) {
                            b.ignore(file);
                        });
                    }
                    if (--b._pending === 0) b.emit('_ready');
                })
                .catch(function (err) {
                    b.emit('error', err);
                });
        });

    []
        .concat(options.exclude)
        .filter(Boolean)
        .forEach(function (u) {
            b.exclude(u);

            b._pending++;
            glob(u)
                .then(function (files) {
                    files.forEach(function (file) {
                        b.exclude(file);
                    });
                    if (--b._pending === 0) b.emit('_ready');
                })
                .catch(function (err) {
                    b.emit('error', err);
                });
        });

    []
        .concat(options.external)
        .filter(Boolean)
        .forEach(function (x) {
            var xs = splitOnColon(x);
            if (xs.length === 2) {
                add(xs[0], { expose: xs[1] });
            } else if (/\*/.test(x)) {
                b.external(x);
                b._pending++;
                glob(x)
                    .then(function (files) {
                        files.forEach(function (file) {
                            add(file, {});
                        });
                        if (--b._pending === 0) b.emit('_ready');
                    })
                    .catch(function (err) {
                        b.emit('error', err);
                    });
            } else add(x, {});

            function add(x, opts) {
                if (/^[/.]/.test(x)) b.external(path.resolve(x), opts);
                else b.external(x, opts);
            }
        });
}

function splitOnColon(f) {
    var pos = f.lastIndexOf(':');
    if (pos == -1) {
        return [f]; // No colon
    } else {
        if (/[a-zA-Z]:[\\/]/.test(f) && pos == 1) {
            return [f]; // Windows path and colon is part of drive name
        } else {
            return [f.substr(0, pos), f.substr(pos + 1)];
        }
    }
}

const test = require('tap').test;
const deps = require('../');
const { readFileSync } = require('fs');
const { globSync } = require('glob');
const path = require('path');
const Resolver = require('../../mendel-resolver');

const jsFixtures = globSync(__dirname + '/fixtures/js/**/*.js');

const jsResolver = new Resolver({
    basedir: __dirname,
    runtimes: ['browser', 'main'],
});

jsFixtures
    .filter((file) => file.endsWith('index.js'))
    .forEach((file) => {
        const dirname = path.dirname(file);
        jsResolver.setBaseDir(dirname);

        test(dirname, function (t) {
            return deps({
                file,
                source: readFileSync(file, 'utf8'),
                resolver: jsResolver,
            }).then((deps) => {
                // foo, process, and global
                t.equal(Object.keys(deps).length, 3);

                const fooDep = deps['./foo'];
                t.match(fooDep.browser, /foo\/browser.js$/);
                t.match(fooDep.main, /foo\/server.js$/);
            });
        });
    });

const test = require('tap').test;
const deps = require('../');
const { readFileSync } = require('fs');
const { globSync } = require('glob');
const path = require('path');
const Resolver = require('../../mendel-resolver');

const cssFixtures = globSync(__dirname + '/fixtures/css/**/*.css');

const cssResolver = new Resolver({
    cwd: __dirname,
    runtimes: ['browser', 'main'],
});

cssFixtures
    .filter((file) => file.endsWith('index.css'))
    .forEach((file) => {
        const dirname = path.dirname(file);
        cssResolver.setBaseDir(dirname);

        test(dirname, function (t) {
            return deps({
                file,
                source: readFileSync(file, 'utf8'),
                resolver: cssResolver,
            }).then((deps) => {
                t.equal(
                    Object.keys(deps).length,
                    3,
                    'malformed import is skipped without dropping the other dependencies'
                );

                t.equal(
                    deps["url('./foo.css')"],
                    false,
                    'url is not traversed or imported, it is treated as an external/lazy dependency'
                );

                const barDep = deps['./bar.css'];
                t.match(barDep.browser, /bar\.css$/);
                t.match(barDep.main, /bar\.css$/);

                const bazDep = deps['./baz.css'];
                t.match(
                    bazDep.browser,
                    /baz\.css$/,
                    'media query suffix is stripped from the import target'
                );
                t.match(bazDep.main, /baz\.css$/);
            });
        });
    });

